Proceso BuscarValor
    Dimension numeros[5] Como Entero;
    Definir Mutable objetivo Como Entero <- 0;
    Para i <- 0 Hasta 4 Con Paso 1 Hacer
        Leer numeros[i];
    FinPara
    Leer objetivo;
    Definir Mutable indice Como Entero <- -1;
    Para i <- 0 Hasta 4 Con Paso 1 Hacer
        Si numeros[i] = objetivo Entonces
            indice <- i;
        FinSi
    FinPara
    Escribir indice;
FinProceso
